Here's an example of what your Windows Forms application code might look like:

```csharp
using System;
using System.Windows.Forms;
using System.Runtime.InteropServices;
using System.Threading;
using System.Threading.Tasks;

public class AutoClickerForm : Form
{
    private System.Windows.Forms.Timer clickTimer = new System.Windows.Forms.Timer();
    private Button startButton;
    private Button rightClickButton;
    private Button leftClickButton;
    private TextBox intervalTextBox;
    private Label coordinatesLabel;
    private uint mouseX = 0, mouseY = 0;
    private int clickType = MOUSEEVENTF_LEFTDOWN | MOUSEEVENTF_LEFTUP; // Default to left click

    private const int MOUSEEVENTF_LEFTDOWN = 0x02;
    private const int MOUSEEVENTF_LEFTUP = 0x04;
    private const int MOUSEEVENTF_RIGHTDOWN = 0x08;
    private const int MOUSEEVENTF_RIGHTUP = 0x10;

    [DllImport("user32.dll")]
    public static extern void mouse_event(uint dwFlags, uint dx, uint dy, uint cButtons, uint dwExtraInfo);

    [DllImport("user32.dll")]
    public static extern bool SetCursorPos(int x, int y);

    [DllImport("user32.dll")]
    private static extern short GetAsyncKeyState(int vKey);

    public AutoClickerForm()
    {
        initControls();
    }

    private void initControls()
    {
        // Interval TextBox
        intervalTextBox = new TextBox();
        intervalTextBox.Location = new System.Drawing.Point(10, 10);
        intervalTextBox.Width = 100;
        Controls.Add(intervalTextBox);

        // Start Button
        startButton = new Button();
        startButton.Text = "Start";
        startButton.Location = new System.Drawing.Point(10, 40);
        startButton.Click += (sender, args) => ToggleClicker();
        Controls.Add(startButton);

        // Right Click Button
        rightClickButton = new Button();
        rightClickButton.Text = "Right Click";
        rightClickButton.Location = new System.Drawing.Point(120, 40);
        rightClickButton.Click += (sender, args) => clickType = MOUSEEVENTF_RIGHTDOWN | MOUSEEVENTF_RIGHTUP;
        Controls.Add(rightClickButton);

        // Left Click Button
        leftClickButton = new Button();
        leftClickButton.Text = "Left Click";
        leftClickButton.Location = new System.Drawing.Point(230, 40);
        leftClickButton.Click += (sender, args) => clickType = MOUSEEVENTF_LEFTDOWN | MOUSEEVENTF_LEFTUP;
        Controls.Add(leftClickButton);

        // Coordinates Label
        coordinatesLabel = new Label();
        coordinatesLabel.Location = new System.Drawing.Point(10, 70);
        coordinatesLabel.Width = 200;
        coordinatesLabel.Text = "Position: 0, 0";
        Controls.Add(coordinatesLabel);

        // Set up the timer
        clickTimer.Tick += (sender, args) => ClickMouse();

        // Set up the KeyDown event to capture hotkeys
        KeyDown += AutoClickerForm_KeyDown;
        KeyPreview = true;
    }

    private void ToggleClicker()
    {
        if (clickTimer.Enabled)
        {
            clickTimer.Stop();
            startButton.Text = "Start";
        }
        else
        {
            if (int.TryParse(intervalTextBox.Text, out int interval))
            {
                clickTimer.Interval = interval;
                clickTimer.Start();
                SetCursorPos((int)mouseX, (int)mouseY);
                startButton.Text = "Stop";
            }
            else
            {
                MessageBox.Show("Invalid interval. Enter interval in milliseconds.");
            }
        }
    }

    private void ClickMouse()
    {
        mouse_event(clickType, mouseX, mouseY, 0, 0);
    }

    private void AutoClickerForm_KeyDown(object sender, KeyEventArgs e)
    {
        if (e.Control && e.KeyCode == Keys.L)
        {
            mouseX = (uint)Cursor.Position.X;
            mouseY = (uint)Cursor.Position.Y;
            coordinatesLabel.Text = $"Position: {mouseX}, {mouseY}";
        }
    }

    [STAThread]
    public static void Main()
    {
        Application.EnableVisualStyles();
        Application.SetCompatibleTextRenderingDefault(false);
        Application.Run(new AutoClickerForm());
    }
}
```

